from datetime import datetime
import math


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = float(hourly_rate)

    def fee(self, entry: datetime, exit: datetime) -> float:
        duration_seconds = (exit - entry).total_seconds()
        if duration_seconds <= 0:
            return 0.0

        # Stays longer than 24 hours (24 * 3600 = 86400 seconds)
        if duration_seconds > 86400:
            return 200.00

        # Stays of at most 15 minutes (15 * 60 = 900 seconds) are free
        if duration_seconds <= 900:
            return 0.0

        # Every started hour is charged as a full hour
        hours = math.ceil(duration_seconds / 3600)
        total_fee = hours * self.hourly_rate

        return round(total_fee, 2)
